import React from 'react';
import type { CashVoucherCompanyAllocationDto } from '../../services/kt/models';
import { formatMoneyVnd } from '../../utils/formatters';
import styles from '../../styles/documentForm.module.css';

const METHOD_LABEL: Record<string, string> = {
  Manual: 'Nhập đích danh',
  Equal: 'Phân bổ bình quân',
  equal: 'Phân bổ bình quân', // legacy casing
  Ratio: 'Phân bổ tỷ lệ',
};

export type CompanyAllocationViewSectionProps = {
  lines: CashVoucherCompanyAllocationDto[];
  testIdPrefix: string;
  onOpenSlideout?: () => void;
  canEdit?: boolean;
};

export const CompanyAllocationViewSection: React.FC<CompanyAllocationViewSectionProps> = ({
  lines,
  testIdPrefix,
  onOpenSlideout,
  canEdit = false,
}) => {
  if (!lines || lines.length === 0) return null;
  const method = lines.find(l => !l.isRoundingDiff)?.method ?? lines[0]?.method ?? '';
  const methodLabel = METHOD_LABEL[method] ?? method;
  const normal = lines.filter(l => !l.isRoundingDiff);
  const cl = lines.filter(l => l.isRoundingDiff);
  const sum = lines.reduce((s, l) => s + (Number(l.amount) || 0), 0);
  const byLine = lines.some(l => l.cashVoucherLineId);
  const scopeLabel = byLine ? 'theo dòng CT' : 'chung phiếu';

  return (
    <div
      className={styles.formSection}
      data-testid={`${testIdPrefix}-company-allocation-section`}
      style={{ marginTop: 16 }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, marginBottom: 8 }}>
        <h3 className={styles.sectionTitle} style={{ margin: 0 }}>
          Phân bổ theo đơn vị cơ sở
          {methodLabel ? <span style={{ fontWeight: 400, marginLeft: 8, fontSize: 13 }}>({methodLabel} · {scopeLabel})</span> : null}
        </h3>
        {canEdit && onOpenSlideout && (
          <button
            type="button"
            data-testid={`${testIdPrefix}-company-allocation-edit-btn`}
            onClick={onOpenSlideout}
            style={{ fontSize: 13, background: 'none', border: 'none', color: '#0369a1', cursor: 'pointer', padding: 0 }}
          >
            Sửa phân bổ
          </button>
        )}
      </div>
      <div className={styles.tableWrapper}>
        <table className={styles.linesTable}>
          <thead>
            <tr>
              {byLine && <th>Dòng CT</th>}
              <th>Mã ĐVCS</th>
              <th>Tên đơn vị</th>
              <th>Tỷ lệ %</th>
              <th>Số tiền</th>
              <th>Ghi chú</th>
            </tr>
          </thead>
          <tbody>
            {normal.map((line, idx) => (
              <tr key={line.id || `${line.targetCompanyCode}-${idx}`} data-testid={`${testIdPrefix}-company-allocation-row-${idx}`}>
                {byLine && <td style={{ fontSize: 12 }}>{line.cashVoucherLineId?.slice(0, 8) ?? '—'}</td>}
                <td>{line.targetCompanyCode}</td>
                <td>{line.targetCompanyName || '—'}</td>
                <td>{Number(line.ratio) || 0}</td>
                <td>{formatMoneyVnd(line.amount)}</td>
                <td>—</td>
              </tr>
            ))}
            {cl.map((line, idx) => (
              <tr key={`cl-${line.id || idx}`} data-testid={`${testIdPrefix}-company-allocation-cl-${idx}`}>
                {byLine && <td style={{ fontSize: 12 }}>{line.cashVoucherLineId?.slice(0, 8) ?? '—'}</td>}
                <td>{line.targetCompanyCode}</td>
                <td>{line.targetCompanyName || '—'}</td>
                <td>—</td>
                <td>{formatMoneyVnd(line.amount)}</td>
                <td><strong>CL</strong></td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <td colSpan={byLine ? 4 : 3}><strong>Tổng</strong></td>
              <td data-testid={`${testIdPrefix}-company-allocation-sum`}><strong>{formatMoneyVnd(sum)}</strong></td>
              <td />
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};
